// Object that owns cleaner / cleanDone / cleanTask for a board line: the row
// itself for turnovers, otherwise the extra (sofa, refresh) built for the same
// apartment — so a check-in-only arrival needing sofa beds stays ONE line.
function _opsCleanTarget(row) {
