// One tbody for the whole day: Daily Ops rows first (with their cleaning cells
// attached), then the cleans that have no checkout row of their own.
function _opsBoardRowsHtml() {
  const main = (_opsRows || []).map(function (r, i) { return { r: r, i: i }; });
  const merged = {};
  main.forEach(function (p) {
    const t = _opsCleanTarget(p.r);
    if (t && t !== p.r) merged[_opsCleanStorageKey(t)] = true;
  });
  let extras = (_opsCleanExtras || []).filter(function (ex) {
    return !merged[_opsCleanStorageKey(ex)];
  });
  if ((window._opsCleanSort || 'status') === 'route') {
    const nameOf = function (r) {
      const t = _opsCleanTarget(r) || r;
      const l = (typeof _opsCleanerList === 'function') ? _opsCleanerList(t) : [];
      return String(l[0] || '\uFFFF');
    };
    const cmp = function (a, b) {
      const c = nameOf(a).localeCompare(nameOf(b), 'el', { sensitivity: 'base' });
      if (c) return c;
      if (typeof window.aptProximityCompare === 'function') {
        const pc = window.aptProximityCompare(_opsAptOf(a), _opsAptOf(b));
        if (pc) return pc;
      }
      return String(a.aptName || '').localeCompare(String(b.aptName || ''));
    };
    main.sort(function (a, b) { return cmp(a.r, b.r); });
    extras = extras.slice().sort(cmp);
  }
  let n = 0;
  const html = main.map(function (p) { n++; return _opsBuildRow(p.r, p.i, n); }).join('') +
    extras.map(function (ex) { n++; return _opsBuildExtraRow(ex, n); }).join('');
  if (html) return html;
